        internal static readonly Dictionary<string, string> Values = new Dictionary<string, string>
        {
            ["只读鉴定真实机械手，返回材质、控制接口、接口标记、磨损、装甲/刀刃附加件、套装及游戏原生单件鉴定基准价 base_value。该价格已含套装效果，不再叠加；不是交易报价或鉴定服务报酬。不提交估价、不改变物品或完成委托。需先查询真实物品 ID；鉴定玩法未解锁时返回失败。"] = "Read-only appraisal of a real mechanical hand: material, control interface, interface marking, wear, armor/blade addons, sets and the native per-unit appraisal base_value. The value includes set bonuses; do not add them again. It is not a trade quote or appraisal fee. Does not submit estimates, change items or complete orders. Query the real item ID first. Fails if inspection gameplay is locked.",
            ["只读检查真实香烟的封条、标志、文字和包装外观，返回 visual_assessment（appears_genuine/appears_counterfeit/unknown）及可见异常 issues（seal/logo/lettering/color）。0 为标准外观，-1 为缺失，其他编号为外观变体。仅根据检查界面可见的外观判断，不读取隐藏真伪或自动揭露特性，不质问客人、不改价。不确定时如实说明。需先查询真实物品 ID；目视检查未解锁时返回失败。"] = "Read-only inspection of a real cigarette packet's seal, logo, lettering and packaging. Returns visual_assessment (appears_genuine/appears_counterfeit/unknown) and visible issues (seal/logo/lettering/color). 0 is standard appearance, -1 is missing, other numbers identify variants. Uses only inspection-screen appearance, without reading hidden authenticity, exposing features, confronting customers or changing prices. Report uncertainty. Query the real item ID first. Fails if visual inspection is locked.",
            ["只读检查真实食品券的防伪标、商标、芯片、文字和票面面值，返回 visual_assessment（appears_genuine/appears_counterfeit/unknown）、可见异常 issues（seal/logo/chip/lettering/amount）及 face_value 信用点面值。0 为标准外观，-1 为缺失，其他编号为外观变体。食品券仅发行 40/80/120/160/200/240 信用点面值，面值达到 160 才应有防伪标；芯片缺失或损坏时无法兑换。仅根据检查界面可见外观判断，不读取隐藏真伪或异常标签，不质问客人、不兑换、不改价。需先查询真实物品 ID；目视检查未解锁时返回失败。"] = "Read-only inspection of a real food stamp's security seal, logo, chip, lettering and printed face value. Returns visual_assessment (appears_genuine/appears_counterfeit/unknown), visible issues (seal/logo/chip/lettering/amount) and face_value in credits. 0 is standard appearance, -1 is missing, other numbers identify variants. Stamps are issued only in 40/80/120/160/200/240 credits; only values of 160 or more should carry a security seal. A missing or damaged chip makes the stamp unredeemable. Uses only inspection-screen appearance, without reading hidden authenticity or issue tags, confronting customers, redeeming or changing prices. Query the real item ID first. Fails if visual inspection is locked.",
            ["只读读取真实文档的文字：导师笔记/情报单、带 BOOK_ID 的书籍，以及香烟 / 食品券 / 注射器 / 机械手等指南和通缉令的界面文字。返回 kind、title、body、signature、pages 或 text。主人询问笔记、书籍或指南内容时，先用 find_items / list_container 找到物品，再调用本工具；inspect_item 的 description 只是简介，不能当作全文，也不能根据物品名称编造内容。只读，不打开窗口、不翻页、不改变物品；无法阅读时返回原因。"] = "Read-only text of a real document: mentor notes/intel slips, books with BOOK_ID, and guide/wanted-poster UI text for cigarettes, food stamps, injectors, mechanical hands and similar items. Returns kind, title, body, signature, pages or text. When Master asks about a note, book or guide, locate the item with find_items / list_container first, then call this tool. inspect_item's description is only a summary, not the full text; never invent content from the item name. Read-only: does not open UI, flip pages or change items. Returns a reason when unreadable.",
            ["未知的阅读工具。"] = "Unknown document tool.",
            ["阅读需要先前查询返回的有效 item_id，且不接受其他参数。"] = "Reading requires a valid item_id from a previous query and accepts no other parameters.",
            ["已读取文档文字，未打开界面或改变物品。"] = "Read the document text without opening UI or changing the item.",
            ["文档读取失败，请重新查询物品后重试。"] = "Could not read the document. Query the item again and retry.",
            ["当前状态无法阅读文字，请先恢复健康或解除文盲状态。"] = "Cannot read text in the current state. Recover health or remove the illiterate condition first.",
            ["这个物品没有可读取的文字内容，或当前版本不支持该文档类型。"] = "This item has no readable text, or its document type is not supported in this version.",
            ["只读读取笔记文字，未打开界面、翻页或改变物品。"] = "Read the note text only; no UI opened, pages flipped or items changed.",
            ["只读读取书籍页数据，未翻页或改变物品。"] = "Read the book's page data only; no pages flipped or items changed.",
            ["只读读取单据文字，未改变物品。"] = "Read the slip text only; no items changed.",
            ["只读提取指南 / 纸面界面文字；可能包含标题、图注和界面标签，未打开窗口、翻页或改变物品。"] = "Read-only extraction of guide/paper UI text; may include headings, captions and UI labels. No window opened, pages flipped or items changed.",
            ["未知的鉴定工具。"] = "Unknown inspection tool.",
            ["鉴定需要先前查询返回的有效 item_id，且不接受其他参数。"] = "Inspection requires a valid item_id from a previous query and accepts no other parameters.",
            ["已读取机械手的鉴定特征和基准价，未提交估价。"] = "Read the mechanical hand's appraisal attributes and base value. No estimate was submitted.",
            ["已检查香烟外观，未质问客人或改变物品特性。"] = "Inspected cigarette appearance without confronting the customer or changing item features.",
            ["已检查食品券外观和票面面值，未兑换、质问客人或改变物品。"] = "Inspected the food stamp's appearance and face value without redeeming it, confronting the customer or changing the item.",
            ["票面面值按检查界面显示的信用点返回，不是交易报价或兑换承诺。防伪标应与 160 信用点及以上的面值同时出现；芯片缺失或损坏时无法在配给站兑换，即使其余外观符合标准。未提交估价、未质问客人、未兑换或改变物品。"] = "The face value is the credits shown on the inspection screen, not a trade quote or promise of redemption. A security seal should appear only on face values of 160 credits or more. A missing or damaged chip makes the stamp unredeemable at the commissary even when the other marks are standard. No estimate was submitted, no customer confronted, and nothing redeemed or changed.",
            ["鉴定信息读取失败，请重新查询物品后重试。"] = "Could not read inspection data. Query the item again and retry.",
            ["当前存档尚未解锁目视检查，请先完成对应的教学。"] = "Visual inspection is locked in this save. Complete its tutorial first.",
            ["此物品不属于该鉴定工具支持的类型。"] = "This item is not a type supported by this inspection tool.",
            ["单件鉴定基准价已包含材质、接口、磨损、附加件和套装效果；不是交易报价或鉴定报酬。未提交估价，未完成委托。"] = "The per-unit appraisal base value includes material, interface, wear, addons and set effects. It is not a trade quote or appraisal fee. No estimate was submitted or order completed.",
            ["仅按检查界面可见外观与标准样本比较；不读取隐藏真伪或异常标签。外观符合不保证隐藏真伪，未揭露特性、质问客人或改价。"] = "Compares inspection-screen appearance with the standard sample without reading hidden authenticity or issue tags. Standard appearance does not guarantee hidden authenticity. No features were exposed, customers confronted or prices changed.",
            ["这是历史记录，不代表当前状态。旧查询数据已过期；当前物品、位置、所有权、客人、价格和预算须重新查询。已完成的操作仅作为过去发生的事实保留，不要重复执行。"] = "This is historical, not current state. Old query data has expired; query again for current items, locations, ownership, customers, prices and budgets. Completed operations are retained only as past actions; do not repeat them.",
            ["这是本条消息开始时重新读取的实况，以成功返回的数据为准。刷新失败时当前状态未知，不能用历史记录补齐。柜台物品的 owned=false 表示已非主人所有，不要当作待售自有物品。"] = "Freshly read at the start of this message. Use successful results as the observation. If a refresh fails, current state is unknown; do not fill gaps from history. Counter items with owned=false no longer belong to Master and are not unsold owned goods.",
            ["只读检查当前客人对真实物品的购买偏好、含全部乘区的价格、单件预算及匹配的易货条件。直接使用 current_item_value，不再叠加 pricing 明细中的效果；多件需合计价格。pricing.source 表示价格来源，状态变化后重新查询。需要本轮查询的客人 ID 和物品 ID；不移动或成交。通常直接回答金额和预算是否足够，有影响判断的不确定性时再解释。"] = "Read-only: check the current customer's buying preferences, complete staged price, single-item affordability and matching barter requirements. Use current_item_value directly without reapplying pricing modifiers; sum prices for multiple goods. pricing.source identifies the source; query again after state changes. Requires this turn's customer and item IDs. Does not move or trade. Usually report the amount and affordability directly, explaining uncertainty when it affects the decision.",
            ["当前金额已包含所有价格效果，可直接用于本次预算比较。"] = "The current amount includes all price effects and can be used directly for this budget comparison.",
            ["上柜台前的参考报价，已计入已知价格效果；放上柜台后重新核对。"] = "A pre-placement quote including known price effects; recheck after placing the item on the counter.",
            ["当前物品价值；客人购买预算不用于主人买入物品。"] = "Current item value; the customer's purchase budget does not apply when Master buys goods.",
            ["只读检查真实物品的普通购买偏好、含乘区的售价及剩余预算，并列出匹配的易货条件索引。current_item_value 已含 pricing 中的所有效果，不要再次加价；属性区与市场区分别相加，最终谈价区逐项相乘。柜台顶层读原生报价，其余自有物品预估上柜台后的多种多样、实时价格事件、零售加价及已知客人效果。上柜台、检查或谈价后重新查询；多件须合计报价，不能分别预算内就认为合计够。需要新查询的客人 ID 和物品 ID；不移动、成交或保证完成委托。"] = "Read-only: check a real item's regular buying rules, staged sale price, remaining budget and matching barter indexes. current_item_value already includes every effect in pricing; never add them again. Innate and market percentages add within each stage; final negotiation factors multiply individually. Top-level counter items use the native quote. Other owned items preview variety bonuses, live price events, retail markup and known customer effects on placement. Query again after placement, inspection or negotiation. Sum quotes for multiple items; individual affordability does not imply joint affordability. Requires fresh customer and item IDs. Does not move, trade or guarantee order completion.",
            ["current_item_value 已按游戏的属性、市场、最终谈价乘区计算，勿再次叠加 pricing 中的百分比。柜台顶层物品使用原生实时报价；自有物品上柜台前预估包含多种多样、当前价格事件、零售加价及已知客人效果。未知自定义回调、检查或谈价可能改变价格，上柜台后须重新查询。预算结论仅用于客人购买自有物品；未启用预算时不推断现金。单件预算足够不表示多件合计足够，选择多件时合计各报价并重新查询剩余预算。偏好或易货条件匹配不保证成交或完成委托；此工具不交易或移动物品。"] = "current_item_value already applies the game's innate, market and final negotiation stages; do not reapply percentages from pricing. Top-level counter items use the live native quote. Owned items preview variety bonuses, live price events, retail markup and known customer effects before placement. Unknown custom callbacks, inspection or negotiation may change the quote; query again at the counter. Affordability applies only when this customer buys owned goods; no enabled budget does not imply cash. Sum quotes for multiple goods and refresh the remaining budget. Buying preferences or matching barter requirements do not guarantee a trade or order completion. This tool neither trades nor moves items.",
            ["深空AI：可能是DeepSeek"] = "Deep Space AI: Probably DeepSeek",
            ["深空AI"] = "Deep Space AI",
            ["助手提示词不能超过 {0} 字。"] = "The assistant prompt cannot exceed {0} characters.",
